import{inferRolldownParserLanguage,parseWithRolldownAst}from"#internal/bundler/rolldown.js";const MAX_CACHED_SOURCE_LENGTH=1048576;const cache=new Map;let cachedSourceLength=0;async function parseWorkflowSourceAst(e,t){let n=`${inferRolldownParserLanguage(e)}\0${t}`;if(cache.has(n)){let e=cache.get(n);return cache.delete(n),cache.set(n,e),e}let r=await parseWithRolldownAst(e,t);if(n.length>MAX_CACHED_SOURCE_LENGTH||cache.has(n))return r;cache.set(n,r),cachedSourceLength+=n.length;for(let e of cache.keys()){if(cachedSourceLength<=MAX_CACHED_SOURCE_LENGTH)break;cache.delete(e),cachedSourceLength-=e.length}return r}export{parseWorkflowSourceAst};